  `status` varchar(30) NOT NULL DEFAULT 'request' COMMENT 'Trạng thái dự án',
  `src_link` varchar(600) DEFAULT NULL COMMENT 'Link chứa toàn bộ file của dự án',
  `po_file` varchar(200) DEFAULT NULL COMMENT 'Tên file PO đã lưu',
