  `inv_name` varchar(200) DEFAULT NULL COMMENT 'Tên file hóa đơn gốc',
  `manage_id` varchar(40) DEFAULT NULL COMMENT 'ID dự án bên manage.apsa.agency',
  `closed_at` datetime DEFAULT NULL,
  `closed_by` int(11) DEFAULT NULL,
  `closed_by_name` varchar(120) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_company` (`company_id`),
  KEY `idx_deleted` (`deleted_at`),
  KEY `idx_kind` (`kind`),
  KEY `idx_status` (`status`),
  KEY `idx_manage_id` (`manage_id`)
) ENGINE=InnoDB AUTO_INCREMENT=291 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
